const results = {};

// cheerio
try {
  const cheerio = require("cheerio");
  const $ = cheerio.load("<p>ok</p>");
  results.cheerio = $("p").text() === "ok";
} catch (e) {
  results.cheerio = e.message;
}

// csv-parse (allowed entry)
try {
  const { parse } = require("csv-parse");
  results.csv_parse = typeof parse === "function";
} catch (e) {
  results.csv_parse = e.message;
}

// form-data
try {
  const FormData = require("form-data");
  const f = new FormData();
  f.append("a", "1");
  results.form_data = true;
} catch (e) {
  results.form_data = e.message;
}

// node-fetch (require only)
try {
  const fetchPkg = require("node-fetch");
  results.node_fetch =
    typeof fetchPkg === "function" || typeof fetchPkg.default === "function";
} catch (e) {
  results.node_fetch = e.message;
}

// axios
try {
  const axios = require("axios");
  results.axios = typeof axios === "function";
} catch (e) {
  results.axios = e.message;
}

// moment
try {
  const moment = require("moment");
  results.moment = moment("2025-01-01").year() === 2025;
} catch (e) {
  results.moment = e.message;
}

// uuid
try {
  const { v4: uuidv4 } = require("uuid");
  const id = uuidv4();
  results.uuid = typeof id === "string" && id.length > 0;
} catch (e) {
  results.uuid = e.message;
}

return [{ json: results }];
